import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0008: Why Persist Critical State Before High-risk Actions","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0008-why-persist-before-high-risk-actions.md","filePath":"adr/ADR-0008-why-persist-before-high-risk-actions.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0008-why-persist-before-high-risk-actions.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0008-why-persist-critical-state-before-high-risk-actions" tabindex="-1">ADR-0008: Why Persist Critical State Before High-risk Actions <a class="header-anchor" href="#adr-0008-why-persist-critical-state-before-high-risk-actions" aria-label="Permalink to “ADR-0008: Why Persist Critical State Before High-risk Actions”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/persistence.md §7.3, recovery-engine.md §6.6</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>The engine crashing while executing a recovery action is an expected scenario (power loss, OOM, upgrade). If the action already ran but the record was not persisted, after restart the core does not know the action executed — retrying means a second service restart / second network change, doubling side effects and making it unauditable.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Write-ordering guarantee: the attempt is persisted with <code>outcome = NULL</code> (Executing state) <strong>before</strong> the external action runs; the outcome is written back after execution completes. On crash recovery: NULL outcome means &quot;result may be unknown&quot; — never treated as &quot;not executed&quot; (blind retry) nor as &quot;success&quot; — always re-diagnose (ADR-0013).</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>Write after execution</strong>: the crash window between execution and write loses facts, doubling retry side effects.</li><li><strong>Write everything in memory, flush periodically</strong>: larger window; incomplete audit trail.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: system state is derivable at any crash point; the audit chain is complete (what ran, when). Cons: one extra synchronous write per action (cheap under SQLite WAL); code paths must strictly maintain write ordering.</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li><code>resume_unfinished</code> marks non-terminal runs OutcomeUnknown and stops automatic retry.</li><li>High-risk actions (RiskLevel::High) additionally go through budget and authorization (ADR-0012); persistence is the prerequisite.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};